"""Audit clock domains and illustrative reaction travel; never certify stopping."""
import json,statistics,math
from pathlib import Path
repo=Path(__file__).resolve().parents[1];out=repo.parents[1]/'outputs/r12'
rows=json.loads((out/'v393_stationary/ros_results.json').read_text());summary=json.loads((out/'v393_summary.json').read_text())
wall=[(b['frame_capture_monotonic_ns']-a['frame_capture_monotonic_ns'])/1e9 for a,b in zip(rows,rows[1:])]
sim=[(b['stamp_ns']-a['stamp_ns'])/1e9 for a,b in zip(rows,rows[1:])]
assert len(rows)==20 and all(math.isclose(x,.05) for x in sim)
delays={k:summary['capture_to_status'][k]/1000 for k in ['median_ms','max_ms']}
report={'source_run':'v393_stationary','new_simulation_frames':0,'ppo_updates':0,'clock_audit':{'sim_stamp_intervals_s':sorted(set(sim)),'wall_capture_interval_s':{'median':statistics.median(wall),'max':max(wall)},'sim_time_span_s':sum(sim),'wall_capture_span_s':sum(wall),'sim_span_over_wall_span':sum(sim)/sum(wall)},'source_findings':[{'file':'scripts/r12_sensor_sim.py','finding':'Physics advances physics_hz//20 steps, then world.render and readback, then blocking reader.readline before the next loop. No world.step during response wait.'},{'file':'scripts/r12_sensor_ros.py','finding':'MotionEnvelope dt and mission odometry/map freshness use packet stamp ns; this does not bound elapsed host time while simulator is blocked.'},{'file':'src/arm_practice/lidar_guard.py','finding':'Distance/support divided by a provisional .6s horizon limits commanded approach speed. It is not a measured braking-distance model.'}],'illustrative_constant_speed_travel':[{'speed_m_s':v,'median_delay_travel_m':v*delays['median_ms'],'max_observed_delay_travel_m':v*delays['max_ms']} for v in [.12,.3,.899795667]],'interpretation':'v*t examples assume continuous physical motion at constant speed during observed simulator capture-to-status wall delay. They are neither measured robot travel nor safe speed/braking limits; real camera acquisition and actuator delay differ. The3cm CAD margin is geometric and must not be consumed as a delay allowance.','moving_validation_plan':['Add explicit simulated-time observation/command delay queues so physics can advance while older sensor/control data is pending. Sleeping in the synchronous bridge is insufficient.','Keep capture timestamps unmodified; reject expired/missing or wrong-run data. Separately log sensor age, command age, and applied command.','Begin in simulation at a bounded low-speed straight/stop case only after folded-arm and all sensor/clearance gates; compare baseline and declared delay cases at matching seeds.','Assess XY RMSE<=.03m/s,yaw<=.10rad/s,tilt<4deg,no fall,CAD+3cm,contacts and actual stop travel. Keep existing criteria and do not claim hardware validation.'],'status':'Audit completed; delay-aware moving trial not implemented or executed.'}
(out/'v394_latency_clock_audit.json').write_text(json.dumps(report,indent=2));print(json.dumps(report,indent=2))
